async function loadMediaPreview(mediaId,video){try{
  const status=$('#previewStatus');
  const data=await api('media-preview',{media_id:mediaId});
  if(page!=='import'||selectedMedia!==mediaId||$('#sourceVideo')!==video)return;
  if(data.status==='ready'){
    video.style.display='block';video.src=data.url;video.load();
    status.textContent=data.derived?'Browser preview ready · H.264 copy, reduced resolution. Original recording and full-resolution source frames are preserved.':'Original recording ready for playback.';
  }else if(data.status==='processing'){
    status.textContent='Preparing H.264 browser preview locally. Original recording and extracted frames remain available.';
    setTimeout(()=>loadMediaPreview(mediaId,video),2000);
  }else status.textContent='Playback preview unavailable: '+(data.error||'unknown conversion error')+'. Full source frames remain available below.';
}catch(error){if($('#sourceVideo')===video){const status=$('#previewStatus');if(status)status.textContent='Playback preview unavailable: '+(error.message||error)+'. Full source frames remain available below.'}}}
