 const prior=d.before_rows.length?`<details open><summary>Previously recorded rows · ${d.before_rows.length}</summary><ol>${d.before_rows.map(row=>`<li>${esc(row)}</li>`).join('')}</ol></details>`:'<p>No previously recorded roll rows.</p>';
