 $('#vpAttach-'+id).innerHTML=`<div class="card"><h4>Before → after evidence · ${esc(d.identity.name)} &lt;${esc(d.identity.variant)}&gt; Lv ${esc(d.identity.level)}</h4><p class="small">Owned instance ${esc(inventory_id)} · ${esc(d.identity.slot)} · ${esc(d.identity.rarity||'rarity unknown')}</p><img class="preview" src="/${esc(d.source.context)}" alt="Full game context and tooltip for this exact mod"><p class="small"><a href="/${esc(d.source.frame)}" target="_blank" rel="noopener">Full source frame</a> · ${esc(Number(d.source.timestamp||0).toFixed(1))}s</p>${prior}${disagreement}<p>Source-checked rows · ${d.after_rows.length}</p><p class="small">Main effect: ${esc(d.main_effect)}</p><ol>${rows}</ol><p class="note warn">${esc(d.warning)} ${d.default_tech_gated_count} rows remain gated by unknown Tech activation; ${d.unmodeled_count} rows have no supported formula.</p>${d.replacing_existing&&!d.source_disagreement?`<label class="note warn"><input type="checkbox" id="vpReplace-${esc(id)}"> Replace the previously recorded roll rows for this exact owned instance; backup and Undo will retain them.</label>`:''}${d.already_attached?'<p>Evidence already linked; no further Apply needed.</p>':d.source_disagreement?'<p class="note warn">Reconcile the two recorded sources before attachment. No rows were changed.</p>':`<button class="primary" onclick="applyVideoEvidence('${esc(id)}')">Apply evidence to this owned instance</button>`}</div>`;
