async function showVideoModMath(id){try{
  const d=await api('video-import/mod-math',{proposal_ids:[id],reload_seconds:num('vpMathReload-'+id)});
  const r=d.scenario.component_results,s=d.calibration_sensitivity;
  const rows=d.modifiers.map(m=>`<li>${esc(m.raw_text)} → <b>${esc(m.stat_type.replaceAll('_',' '))}</b>: ${m.value==null?'unmodeled':augFmt(m.value)+'%'} · ${esc(m.calculation_status)} · ${esc(m.confidence)}</li>`).join('');
  $('#vpMath-'+id).innerHTML=`<div class="card"><h3>Separate roll variables · read-only scenario</h3><p class="note warn">${d.scenario.modifiers.tech_gated_rows.length} rows have unknown Tech-level activation and are excluded here. Their actual game effect is unknown, not zero. ${d.scenario.modifiers.unmodeled_rows.some(row=>row.model_exclusion)?'Observed All DMG Boost is also excluded because its damage bucket is unverified. ':''}Use the Component Formula controls for explicit Tech and bucket what-if assumptions.</p><p class="note">${esc(d.baseline_source)}. The 241 DMG / 720 RPM / 40 MAG inputs are an uncalibrated Tier V crafting preview, not your equipped gun. No mod is added or equipped here.</p><ol>${rows}</ol><p>Assumed direct hit ${augFmt(r.baseline_direct_hit)} → <b>${augFmt(r.direct_hit)}</b>; firing-only direct ${augFmt(r.baseline_firing_dps)} → <b>${augFmt(r.direct_firing_dps)}</b> /s. Magazine ${augFmt(r.magazine_unrounded)} unrounded → <b>${r.magazine_bounds?`${r.magazine_bounds.floor}–${r.magazine_bounds.ceil}`:'unknown'}</b> after bounded rounding. ${r.sustained_direct_bounds?`Sustained direct range: ${augFmt(r.sustained_direct_bounds.floor.direct_dps)}–${augFmt(r.sustained_direct_bounds.ceil.direct_dps)} /s under entered reload.`:'Sustained DPS unknown until pre-mod reload is entered.'}</p><p>Elemental event factor <b>${augFmt(r.event_streams.elemental.factor)}×</b>; status event factor <b>${augFmt(r.event_streams.status.factor)}×</b>. Actual event damage and frequency remain unknown.</p><p>Energy / Rapid illustrative noncrit bullet firing: <b>${augFmt(s.calibrations.energy.plain_firing_dps)}</b> / <b>${augFmt(s.calibrations.rapid.plain_firing_dps)}</b> /s. This does not establish total DPS or a winner.</p><details><summary>Assumptions and missing mechanics</summary><ul>${[...d.scenario.assumptions,...s.assumptions].map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details></div>`;
}catch(e){fail(e)}}
async function startVideoAnalysis(){try{let d=await api('video-import/analyze',{media_id:selectedMedia,start:Number($('#start')?.value||0),end:$('#end')?.value?Number($('#end').value):null,interval:Number($('#interval')?.value||1)});videoRunId=d.id;if(d.reused){await refresh();notice('Existing analysis reopened; no duplicate proposals made')}else{currentJob=d.id;pollVideoJob()}}catch(e){fail(e)}}
async function pollVideoJob(){if(!currentJob)return;let j=await(await fetch('/api/jobs/'+currentJob)).json();let el=$('#jobStatus');if(el)el.textContent=`Video analysis: ${j.state} · ${j.progress||0}%${j.error?' · '+j.error:''}`;if(['queued','running'].includes(j.state))setTimeout(pollVideoJob,850);else{currentJob=null;await refresh();notice(j.state==='done'?`${j.proposals} review proposals ready; inventory unchanged`:j.error||j.state)}}
async function saveVideoCorrection(id){try{let changes={catalog_id:val('vpCatalog-'+id),level:num('vpLevel-'+id),rarity:val('vpRarity-'+id)||null,main_effect:val('vpEffect-'+id),attribute_rows:val('vpAttrs-'+id).split('\n').map(x=>x.trim()).filter(Boolean)};await api('video-import/correct',{id,changes});await refresh();notice('Reviewed proposal saved. My Mods unchanged.')}catch(e){fail(e)}}
async function commitVideoProposal(id){try{let d=await api('video-import/commit',{id});await refresh();notice(d.status==='committed'?'Reviewed mod added to My Mods; backup and undo available':'Already in My Mods; no duplicate added')}catch(e){fail(e)}}
async function previewVideoFieldGuide(id){try{
  const result=await api('field-guide/video-preview',{proposal_id:id,profile_id:'personal'});
  const target=$('#vpFieldGuide-'+id);if(!target)return;
  target.innerHTML=`<p class="note">${esc(result.name||result.catalog_id||'Mod')} · ${esc(result.variant||'?')} · source level ${esc(result.proposed_level??'?')} · ${esc(result.decision)}. ${esc(result.numeric_coverage||'Numeric values unknown')} · Tech activation ${esc(result.tech_activation||'unknown')}. This is a read-only observation; your profile and inventory are unchanged.</p>`;
}catch(e){fail(e)}}
async function reviewDistinctVideoCopy(id){try{const reason=val('vpDistinctReason-'+id);await api('video-import/review-distinct-copy',{id,reason});await refresh();notice('Separate-copy evidence recorded. My Mods remains unchanged until Add.')}catch(e){fail(e)}}
async function dismissVideoProposal(id){try{await api('video-import/dismiss',{id});await refresh();notice('Proposal dismissed; inventory unchanged')}catch(e){fail(e)}}
async function undoVideoProposal(id){try{await api('video-import/undo',{id});await refresh();notice('This mod import was undone')}catch(e){fail(e)}}
async function addCheckedVideoMods(runId){try{const plan=state.video_import_plans?.[runId];if(!plan)throw Error('Reopen the instance-aware batch plan');const defer_ids=plan.entries.filter(e=>!['new_owned_copy_candidate','already_committed'].includes(e.classification)).map(e=>e.proposal_id);let d=await api('video-import/commit-checked-batch',{run_id:runId,plan_token:plan.plan_token,defer_ids});await refresh();notice(`${d.added} reviewed new copies added; ${d.deferred} existing or uncertain copies deferred. Backup and batch undo available.`)}catch(e){fail(e)}}
async function undoCheckedVideoMods(runId,batchId){try{let d=await api('video-import/undo-checked-batch',{run_id:runId,batch_id:batchId});await refresh();notice(`${d.removed} mods from this batch removed; saved builds preserved.`)}catch(e){fail(e)}}
function selectCurrentFrame(){let t=$('#sourceVideo')?.currentTime||0;$('#start').value=t.toFixed(2);$('#end').value=(t+1).toFixed(2);$('#interval').value='2';startProcess()}
function selectMedia(id){selectedMedia=id;render()}
function dropFile(e){e.preventDefault();$('#drop').classList.remove('drag');upload(e.dataTransfer.files[0])}
async function upload(f){if(!f)return;try{let o=await fetch('/api/upload',{method:'POST',headers:{'X-Filename':f.name},body:f});let d=await o.json();if(!o.ok)throw Error(d.error);selectedMedia=d.id;await refresh();notice('File saved locally. Select the relevant time range and extract.') }catch(e){fail(e)}}
async function startProcess(){try{let c=$('#crop').value.trim(),crop=null;if(c){let a=c.split(',').map(Number);if(a.length!==4||a.some(x=>!Number.isInteger(x)))throw Error('Crop needs x,y,w,h in pixels');crop={x:a[0],y:a[1],w:a[2],h:a[3]}}let d=await api('process',{media_id:selectedMedia,start:Number($('#start').value||0),end:$('#end').value?Number($('#end').value):null,interval:Number($('#interval').value||3),crop});currentJob=d.id;pollJob()}catch(e){fail(e)}}
async function pollJob(){if(!currentJob)return;let j=await(await fetch('/api/jobs/'+currentJob)).json();let el=$('#jobStatus');if(el)el.innerHTML=`${esc(j.state)} · ${j.progress||0}% <div class="progress"><div style="width:${j.progress||0}%"></div></div>${j.error?esc(j.error):''}`;if(['queued','running'].includes(j.state))setTimeout(pollJob,700);else{currentJob=null;await refresh();notice(j.state==='done'?`${j.observations} readable views ready for review`:j.state==='cancelled'?'Import cancelled; results already saved remain available':j.error)}}
async function cancelJob(){try{await api('cancel',{id:currentJob});notice('Cancellation requested')}catch(e){fail(e)}}
function review(id){let o=state.observations.find(x=>x.id===id);let f=o.fields;$('#reviewArea').innerHTML=`<div class="card"><div class="sectionhead"><h2>Review source frame</h2><span class="badge ${o.confidence<50?'unknown':''}">${Math.round(o.confidence)}% OCR</span></div><div class="obs"><div><img src="/${esc(o.image)}"><p class="small muted">Source: ${esc(state.media.find(m=>m.id===o.media_id)?.name)} · ${o.timestamp?.toFixed(1)||0}s</p><details><summary>Raw OCR text</summary><p class="small muted">${esc(o.ocr)}</p></details></div><div><p class="note warn">${o.fields.identification?.catalog_id?`Catalog match: ${esc(o.fields.identification.catalog_id)} · ${esc(o.fields.identification.ownership)} · ${esc(o.fields.identification.cues?.join('; '))}. ${esc(o.fields.identification.lookup?.unknowns?.join('; ')||'')}`:'Recognition uncertain. Inspect the frame before confirming.'}</p>${o.fields.identification?.icon_reference_url?`<p class="small">Catalog icon reference: <img src="${esc(o.fields.identification.icon_reference_url)}" alt="Catalog icon" width="48" height="48" referrerpolicy="no-referrer" style="vertical-align:middle;background:#20232b"> · visual match not yet verified</p>`:''}<input id="rCatalog" type="hidden" value="${esc(o.fields.identification?.catalog_id||'')}"><div class="field"><label>Item name · ${esc(f.name?.confidence||'unknown')}</label><input id="rName" value="${esc(f.name?.value||'')}"></div><div class="formgrid"><div class="field"><label>Kind</label><select id="rKind"><option value="instance">Crafted item</option><option value="unlock">Account unlock</option><option value="mod_unlock" ${o.fields.identification?.catalog_id?.startsWith('mod:')?'selected':''}>Mod Field Guide unlock</option><option value="accessory_unlock">Accessory unlock</option></select></div><div class="field"><label>Slot</label><select id="rSlot">${slotOptions(f.slot?.value||"")}</select></div><div class="field"><label>Level · ${esc(f.level?.confidence||'unknown')}</label><input id="rLevel" type="number" value="${esc(f.level?.value||'')}"></div><div class="field"><label>Stars · ${esc(f.stars?.confidence||'unknown')}</label><input id="rStars" type="number" value="${esc(f.stars?.value||'')}"></div><div class="field"><label>Direct-hit damage</label><input id="rDmg" type="number" value="${esc(f.damage?.value||'')}"></div><div class="field"><label>RPM</label><input id="rRpm" type="number" value="${esc(f.rpm?.value||'')}"></div><div class="field"><label>Magazine</label><input id="rMag" type="number" value="${esc(f.magazine?.value||'')}"></div><div class="field"><label>Reload seconds</label><input id="rReload" type="number" step=".1" value="${esc(f.reload_seconds?.value||'')}"></div></div><div class="field"><label>Damage origin</label><select id="rOrigin"><option value="tooltip_base">Inventory tooltip/base</option><option value="unknown">Unknown</option></select></div><div class="field"><label>Tooltip damage component</label><select id="rComponent"><option value="unknown">Unknown</option><option value="weapon">Weapon damage</option><option value="status">Status damage</option></select></div><div class="field"><label>Tooltip base context</label><select id="rBaseContext"><option value="unknown">Unknown / buffs may apply</option><option value="unbuffed">Unbuffed, before gear bonus</option></select></div><div class="field"><label>Effect calculation coverage</label><select id="rCoverage"><option value="unresolved">Unresolved</option><option value="verified_no_extra_damage">No extra damage effect verified</option><option value="verified_rule_only">Covered only by selected sourced set rule</option></select></div><div class="field"><label>Set name · ${esc(f.set_name?.confidence||'unknown')}</label><input id="rSet" value="${esc(f.set_name?.value||'')}"></div><div class="field"><label>Observed variable rolls or notes (optional)</label><textarea id="rEffect" rows="4">${esc(o.fields.identification?.catalog_id?(f.mod_roll_lines?.value||[]).join("\n"):[f.effect_text?.value,...(f.attributes?.value||[])].filter(Boolean).join("\n"))}</textarea></div><div class="field"><label>Merge with existing entry (preview carefully)</label><select id="rMerge"><option value="">Create a separate entry</option>${state.inventory.map(i=>`<option value="${i.id}">${esc(i.name)} · ${esc(i.kind)} · ${esc(i.slot||'no slot')}</option>`).join('')}</select></div><div class="actions"><button class="primary" onclick="confirmObs('${id}')">Confirm into inventory</button><button class="secondary" onclick="$('#reviewArea').innerHTML=''">Close</button></div></div></div></div>`;$('#reviewArea').scrollIntoView({behavior:'smooth'})}
function val(id){return $('#'+id)?.value?.trim()||''}
function num(id){let v=val(id);return v===''?null:Number(v)}
async function confirmObs(id){try{let stats={};for(let [k,n] of [['damage','rDmg'],['rpm','rRpm'],['magazine','rMag'],['reload_seconds','rReload']])if(num(n)!==null)stats[k]=num(n);if(val('rSet'))stats.set_name=val('rSet');stats.damage_origin=val('rOrigin');stats.base_component=val('rComponent');stats.base_context=val('rBaseContext');let observation=state.observations.find(x=>x.id===id);let item={catalog_id:val('rCatalog')||null,name:val('rName'),kind:val('rKind'),slot:val('rSlot')||null,variant:observation?.fields?.variant?.value||null,level:num('rLevel'),stars:num('rStars'),stats,effects:{text:val('rCatalog')?'':val('rEffect'),observed_text:val('rCatalog')?val('rEffect'):'',calculation_status:val('rCatalog')?'catalog_partial':val('rCoverage'),rule_ids:val('rCoverage')==='verified_rule_only'?coverageRules(val('rName'),val('rSet')):[]}};let merge=val('rMerge');if(merge){let old=state.inventory.find(i=>i.id===merge);let summary=`Merge into ${old.name} (${old.kind}, ${old.slot||'no slot'})? Existing details will be replaced; undo is available.`;if(!confirm(summary))return}await api('confirm',{observation_id:id,item,merge_id:merge||null});await refresh();notice('Confirmed entry saved')}catch(e){fail(e)}}
function coverageRules(name,setName){let n=(name||'').toLowerCase();if((setName||'').toLowerCase()==='treacherous tides')return ['treacherous_tides_two_weapon'];let rules={'wind intepreter cap':'wind_interpreter_bomber','gilded gauntlets':'gilded_gauntlets_burn_crit','snowline elite vest':'snowline_vortex_repeat'};return rules[n]?[rules[n]]:[]}
function slotOptions(current=''){return `<option value="">Unknown / not equipped</option>${['primary','secondary','melee','helmet','mask','chest','gloves','pants','boots','weapon_mod','helmet_mod','mask_mod','chest_mod','gloves_mod','pants_mod','boots_mod','accessory'].map(s=>`<option ${current===s?'selected':''}>${s}</option>`).join('')}`}
function inventoryPage(){let q=window.invQ||'',kind=window.invKind||'';let items=state.inventory.filter(i=>(!q||(i.name+' '+(i.family||'')).toLowerCase().includes(q.toLowerCase()))&&(!kind||i.kind===kind));return `<div class="sectionhead"><h2>Confirmed inventory</h2><div class="actions"><button class="secondary" onclick="undo()">Undo last change</button><button class="primary" onclick="editItem()">+ Add item</button></div></div><div class="grid two"><div><div class="inline" style="margin-bottom:14px"><input class="grow" placeholder="Search names and families" value="${esc(q)}" oninput="window.invQ=this.value;render()"><select onchange="window.invKind=this.value;render()"><option value="">All types</option>${['instance','unlock','mod_unlock','accessory_unlock'].map(k=>`<option ${kind===k?'selected':''}>${k}</option>`).join('')}</select></div><div class="list">${items.length?items.map(i=>`<div class="row"><div class="inline">${entryArt(catalogEntry(i.effects?.catalog_id),true)}<div><div class="itemtitle"><b>${esc(i.name)}</b><span class="badge">${esc(i.kind)}</span></div><small>${esc(i.slot||'slot unknown')} · level ${i.level??'?'} · ${esc(i.variant||'no variant recorded')} · last seen ${fmtDate(i.last_seen)}</small></div></div><button class="secondary" onclick="editItem('${i.id}')">Details</button></div>`).join(''):empty('No confirmed matches','Review an import or add an item manually.')}</div><p class="footertext">Items missing from later recordings stay here. Ownership coverage is limited to confirmed entries.</p></div><div id="itemEditor">${editorHtml()}</div></div>`}
function editorHtml(){if(!editing)return `<div class="card"><h2>Inventory coverage</h2><p class="tagline">${state.inventory.length} confirmed entries across ${new Set(state.inventory.map(i=>i.slot).filter(Boolean)).size} equipment slots. Unseen ownership is unknown.</p><div class="line"></div><p class="muted small">Select an item to inspect its evidence and update chosen attributes, or add an account unlock manually.</p></div>`;let i=editing==='new'?{}:state.inventory.find(x=>x.id===editing)||{};return `<div class="card"><h2>${i.id?'Edit item':'Add confirmed item'}</h2><div class="formgrid"><div class="field"><label>Name</label><input id="iName" value="${esc(i.name||'')}"></div><div class="field"><label>Kind</label><select id="iKind">${['instance','unlock','mod_unlock','accessory_unlock'].map(k=>`<option ${i.kind===k?'selected':''}>${k}</option>`).join('')}</select></div><div class="field"><label>Slot</label><select id="iSlot">${slotOptions(i.slot)}</select></div><div class="field"><label>Family</label><input id="iFamily" value="${esc(i.family||'')}"></div><div class="field"><label>Variant</label><input id="iVariant" value="${esc(i.variant||'')}"></div><div class="field"><label>Level</label><input id="iLevel" type="number" value="${i.level??''}"></div><div class="field"><label>Stars</label><input id="iStars" type="number" value="${i.stars??''}"></div><div class="field"><label>Damage per direct hit</label><input id="iDamage" type="number" value="${i.stats?.damage??''}"></div><div class="field"><label>RPM</label><input id="iRpm" type="number" value="${i.stats?.rpm??''}"></div><div class="field"><label>Magazine</label><input id="iMag" type="number" value="${i.stats?.magazine??''}"></div><div class="field"><label>Reload seconds</label><input id="iReload" type="number" step=".1" value="${i.stats?.reload_seconds??''}"></div></div><div class="field" style="margin-top:13px"><label>Damage origin</label><select id="iOrigin"><option value="unknown" ${!i.stats?.damage_origin||i.stats?.damage_origin==='unknown'?'selected':''}>Unknown / legacy</option><option value="tooltip_base" ${i.stats?.damage_origin==='tooltip_base'?'selected':''}>Inventory tooltip/base</option><option value="combat_hit" ${i.stats?.damage_origin==='combat_hit'?'selected':''}>Combat hit (needs context record)</option></select></div><div class="field"><label>Tooltip damage component</label><select id="iComponent"><option value="unknown" ${!i.stats?.base_component||i.stats?.base_component==='unknown'?'selected':''}>Unknown</option><option value="weapon" ${i.stats?.base_component==='weapon'?'selected':''}>Weapon damage</option><option value="status" ${i.stats?.base_component==='status'?'selected':''}>Status damage</option></select></div><div class="field"><label>Tooltip base context</label><select id="iBaseContext"><option value="unknown" ${!i.stats?.base_context||i.stats?.base_context==='unknown'?'selected':''}>Unknown / buffs may apply</option><option value="unbuffed" ${i.stats?.base_context==='unbuffed'?'selected':''}>Unbuffed, before gear bonus</option></select></div><div class="field"><label>Effect calculation coverage</label><select id="iCoverage"><option value="unresolved" ${!i.effects?.calculation_status||i.effects?.calculation_status==='unresolved'?'selected':''}>Unresolved</option><option value="verified_no_extra_damage" ${i.effects?.calculation_status==='verified_no_extra_damage'?'selected':''}>No extra damage effect verified</option><option value="verified_rule_only" ${i.effects?.calculation_status==='verified_rule_only'?'selected':''}>Covered only by selected sourced rule</option></select></div><div class="field"><label>Set name (exact)</label><input id="iSet" value="${esc(i.stats?.set_name||'')}"></div><div class="field"><label>Other observed stats (JSON object)</label><textarea id="iStats" rows="3">${esc(JSON.stringify(Object.fromEntries(Object.entries(i.stats||{}).filter(([k])=>!['damage','rpm','magazine','reload_seconds','set_name','damage_origin','base_component','base_context'].includes(k))),null,2))}</textarea></div><div class="field"><label>Effect / selected attributes</label><textarea id="iEffect" rows="3">${esc(i.effects?.text||'')}</textarea></div>${i.evidence?.length?`<p class="small muted">Evidence: ${i.evidence.map(e=>`<a href="/${esc(e.image)}" target="_blank">frame ${e.timestamp?.toFixed(1)||0}s</a>`).join(', ')}</p>`:''}<div class="actions"><button class="primary" onclick="saveItem('${i.id||''}')">Save item</button>${i.id?`<button class="secondary" onclick="evaluateItem('${i.id}')">Evaluate acquisition</button><button class="secondary danger" onclick="archiveItem('${i.id}')">Archive</button>`:''}<button class="secondary" onclick="editing=null;render()">Close</button></div><div id="itemEvaluation"></div></div>`}
async function evaluateItem(id){try{let item=state.inventory.find(i=>i.id===id),uses=state.loadouts.filter(b=>b.item_ids.includes(id));let msg=`Used in ${uses.length} saved build${uses.length===1?'':'s'}. `;if(item.slot==='primary'){let d=await api('optimize',{assumptions:{duration:45,hit_rate:0.8}}),rank=d.supported.findIndex(x=>x.item.id===id);msg+=rank>=0?`Direct-hit baseline rank ${rank+1} of ${d.supported.length} calculable owned weapons at 45s and 80% accuracy. Effects and set interactions can change this.`:`Baseline uncalculable; missing damage, RPM, magazine or reload. Effects can still enable a different build.`}else msg+='Its set, mod, support or accessory interactions are not yet calculable. Check whether it enables a new legal loadout and verify its activation tooltip.';$('#itemEvaluation').innerHTML=`<p class="note warn" style="margin-top:15px">${esc(msg)}</p>`}catch(e){fail(e)}}
function editItem(id){editing=id||'new';render()}
async function saveItem(id){try{let stats=JSON.parse(val('iStats')||'{}');if(typeof stats!=='object'||Array.isArray(stats))throw Error('Stats must be a JSON object');for(let [k,n] of [['damage','iDamage'],['rpm','iRpm'],['magazine','iMag'],['reload_seconds','iReload']]){if(num(n)!==null)stats[k]=num(n);else delete stats[k]}if(val('iSet'))stats.set_name=val('iSet');stats.damage_origin=val('iOrigin');stats.base_component=val('iComponent');stats.base_context=val('iBaseContext');await api('item',{id:id||undefined,name:val('iName'),kind:val('iKind'),slot:val('iSlot')||null,family:val('iFamily'),variant:val('iVariant'),level:num('iLevel'),stars:num('iStars'),stats,effects:{text:val('iEffect'),calculation_status:val('iCoverage'),rule_ids:val('iCoverage')==='verified_rule_only'?coverageRules(val('iName'),val('iSet')):[]}});editing=null;await refresh();notice('Item saved')}catch(e){fail(e)}}
async function archiveItem(id){if(!confirm('Archive this item? Undo is available.'))return;try{await api('archive',{id});editing=null;await refresh()}catch(e){fail(e)}}
async function undo(){try{let d=await api('undo',{});await refresh();notice(d.ok?'Last inventory change undone':'No change to undo')}catch(e){fail(e)}}

function catalogPage(){let c=state.catalog_coverage||{};return `<div class="card"><div class="kicker">VERSIONED KNOWLEDGE LAYER</div><h2>Search all known entries</h2><p class="tagline">${c.counts?.mods||0} distinct mod identities · ${c.fully_resolved_mod_identities||0} identities with a complete numeric level · ${c.exact_mod_level_profiles||0} complete identity-level profiles · ${c.counts?.weapons||0} weapons · ${c.counts?.armor||0} armor · ${c.counts?.sets||0} sets. Pinned community source: ${esc(c.snapshot?.source_date||'unknown')}; current community mod snapshot: ${esc(c.current_snapshot?.retrieved_utc?.slice(0,10)||'unknown')}. ${c.current_snapshot?.rejected_records||0} current page records could not be parsed; ${c.effect_text_conflicts||0} effect descriptions conflict. Official rules apply only where verified. Unseen means ownership unknown.</p><div class="inline"><input class="grow" id="catalogQ" placeholder="Name, family, tree, variant or effect" onkeydown="if(event.key==='Enter')loadCatalog()"><select id="catalogKind"><option value="">All types</option><option value="mod">Mods</option><option value="weapon">Weapons</option><option value="armor">Armor</option><option value="set">Sets</option></select><button class="primary" onclick="loadCatalog()">Search</button></div><div id="catalogResults" style="margin-top:18px">${catalogResult?catalogResultsHtml():''}</div></div>`}
async function loadCatalog(offset=0){try{let q=encodeURIComponent(val('catalogQ')||''),kind=encodeURIComponent(val('catalogKind')||'');catalogResult=await(await fetch(`/api/catalog?q=${q}&kind=${kind}&offset=${offset}`)).json();$('#catalogResults').innerHTML=catalogResultsHtml()}catch(e){fail(e)}}
function catalogResultsHtml(){let d=catalogResult;if(!d)return '';return `<p class="small muted">${d.total} matching entries · showing ${d.offset+1}–${Math.min(d.offset+d.entries.length,d.total)} · exact level attributes available for ${d.coverage.exact_mod_level_profiles} mod-level records</p><div class="list">${d.entries.map(e=>`<div class="row"><div>${e.image_url?`<img src="${esc(e.image_url)}" alt="${esc(e.name)} icon" loading="lazy" referrerpolicy="no-referrer" width="44" height="44" style="float:left;margin-right:12px;background:#20232b;border-radius:6px">`:''}<b>${esc(e.name)} ${e.variant?`&lt;${esc(e.variant)}&gt;`:''}</b><small>${esc(e.kind)} · ${esc(e.slot||e.family||'')} · ${esc(e.tree||'')} · ${esc(e.data_status||'')}</small><small>${esc(e.primary_effect||e.effect||'Effect details unresolved')}</small><small>${esc(e.acquisition?.method||e.acquisition?.exact_path||e.acquisition||'Acquisition path unknown')}</small></div><div>${tag(e.owned?'owned':e.sighting==='locked'?'locked':e.sighting==='unlocked'?'seen unlocked':'unknown')}<br><button class="secondary" onclick="inspectCatalog('${esc(e.id)}')">Inspect</button>${e.source_url?`<br>${sourceReference(e.source_url,'Source')}`:''}</div></div>`).join('')||empty('No matches','Try another name or category.')}</div><div id="catalogDetail"></div><div class="actions" style="margin-top:14px"><button class="secondary" ${d.offset<=0?'disabled':''} onclick="loadCatalog(${Math.max(0,d.offset-30)})">Previous</button><button class="secondary" ${d.offset+30>=d.total?'disabled':''} onclick="loadCatalog(${d.offset+30})">Next</button></div>`}
async function inspectCatalog(id,level,shiny=false){let url='/api/catalog/'+encodeURIComponent(id)+(level?'?level='+level:'')+(shiny?(level?'&':'?')+'shiny=1':'');let d=await(await fetch(url)).json();let e=d.entry;let attributes=(d.known_attributes||[]).map(a=>`<div class="row"><div><b>${esc(a.name)}</b> · tier ${esc(a.tier)} · ${a.value_percent===null?'value unresolved':`+${esc(a.value_percent)}%`}${a.conditional_bonus_percent!=null?` · additional +${esc(a.conditional_bonus_percent)}% when ${esc(a.condition||'condition met')}`:a.condition?` · ${esc(a.condition)}`:''}</div><small>${esc(a.source_status||a.source||'Source unresolved')}</small></div>`).join('');let candidates=(d.effect_candidates||[]).map(x=>`<li>${esc(x)}</li>`).join('');$('#catalogDetail').innerHTML=`<div class="card" style="margin-top:16px"><h3>${esc(e.display_name||e.name)}</h3><p>${esc(d.primary_effect||e.effect||'Effect level unresolved')}</p>${e.kind==='mod'?`<p class="small">System: ${esc(e.system_generation||'unverified')} · Shiny listed: ${e.shiny_available_in_secondary_catalog?'yes (community catalog)':'unverified'} · numeric coverage: ${esc(d.attribute_coverage||'unresolved')}</p><label>Field Guide level <select onchange="inspectCatalog('${esc(id)}',this.value,false)"><option value="">Select</option>${Array.from({length:17},(_,n)=>`<option value="${n+1}" ${d.level===n+1?'selected':''}>${n+1}</option>`).join('')}</select></label><label style="margin-left:12px">Shiny Lv. 17 <input type="checkbox" ${d.shiny?'checked':''} onchange="inspectCatalog('${esc(id)}',17,this.checked)"></label>${attributes?`<div class="list" style="margin-top:12px">${attributes}</div>`:`<p class="small">Ordered attribute tiers: ${esc(d.attribute_tiers?.map(a=>a.name+' '+a.tier).join('; ')||d.level_profile?.join(', ')||'select a level')}</p>`}<p class="small">Possible dungeon crate difficulties: ${esc(d.possible_crate_difficulties?.join(', ')||'select a level')}. Entry-specific drop location and rate unknown.</p>${d.shiny_acquisition?`<p class="small">Shiny paths: ${esc(d.shiny_acquisition.paths.join('; '))}; entry eligibility ${esc(d.shiny_acquisition.entry_specific_eligibility)}. ${sourceReference(d.shiny_acquisition.source,'Official source')}</p>`:''}`:''}${candidates?`<details><summary>Detail-page effect descriptions (${d.effect_candidates.length}); effect-level mapping unresolved</summary><ul>${candidates}</ul></details>`:''}<p class="small">Structured effects: ${esc(JSON.stringify(d.known_effects||[]))}</p><p class="small">Activation: ${esc(JSON.stringify(e.activation_conditions||[]))} · Stacking: ${esc(e.stacking_rule||'unknown')}</p><p class="note warn">${esc((d.unknowns||[]).join(' ')||'No additional catalog unknowns recorded.')}</p></div>`}

function buildsPage(){return `<div class="grid two"><div class="card"><div class="kicker">LOADOUT EDITOR</div><h2>Assemble owned gear</h2><div class="field"><label>Build name</label><input id="buildName" placeholder="e.g. Boss damage · current setup"></div><div class="field"><label>Notes / playstyle</label><textarea id="buildNotes" rows="2"></textarea></div><div class="list">${state.inventory.length?state.inventory.map(i=>`<label class="row"><span><b>${esc(i.name)}</b><small>${esc(i.slot||'no slot')} · ${esc(i.kind)}</small></span><input type="checkbox" value="${i.id}" ${chosen.includes(i.id)?'checked':''} onchange="toggleChoice('${i.id}',this.checked)"></label>`).join(''):empty('No confirmed gear yet','Import and review footage or add items manually.')}</div><button class="primary" style="margin-top:16px" onclick="saveBuild()">Save build</button></div><div><div class="card"><h2>Saved builds</h2><div class="list">${state.loadouts.length?state.loadouts.map(b=>`<div class="row"><div><b>${esc(b.name)}</b><small>${b.item_ids.length} pieces · updated ${fmtDate(b.updated)}</small></div><button class="secondary" onclick="loadBuild('${b.id}')">Edit</button></div>`).join(''):empty('No builds saved','Select owned items to make your first snapshot.')}</div></div><div class="card" style="margin-top:18px"><h2>Build audit</h2><p class="tagline">The editor rejects duplicate equipment slots. Recorded effects without verified activation or stacking rules are flagged in comparison.</p></div></div></div>`}
