 return '<option value="">No Top mod · saved plan as recorded</option>'+ids.map(([id,record])=>`<option value="${esc(id)}">${esc(id.slice('mod:chest_mod:'.length).split('-').map(part=>part[0].toUpperCase()+part.slice(1)).join(' '))} · Lv ${esc(record.level)}</option>`).join('');
