function guideTopContext(id){const build=(state.planned_builds||[]).find(item=>item.id===id);if(!build)return 'Choose a saved plan to see whether it already has a Top mod. The optional choice below is separate and never saves or equips it.';return build.slots?.top?.mod_id?'This saved plan has a Top mod. The optional choice below previews a different candidate separately; it does not replace the saved choice or combine effects into total DPS.':'This saved plan has no Top mod. The optional choice below previews a candidate separately; it does not equip it, change the plan, or combine effects into total DPS.'}
function guideBuildChecklist(build,profile,options={}){
 if(!build)return {next:'Choose a saved plan to see one useful next action.',action:null,checks:[]};
 const slots=build.slots||{},armor=['helmet','top','bottoms','shoes','gloves','mask'];
 const missingArmor=armor.filter(slot=>!slots[slot]?.catalog_id);
 const selectedMods=Object.entries(slots).filter(([,item])=>item?.mod_id);
 const levels=state.field_guide_profiles?.[profile]?.levels||{};
 const unmatched=selectedMods.filter(([,item])=>Number(levels[item.mod_id]?.level)!==Number(item.mod_level)||!levels[item.mod_id]);
 const firstUnmatched=unmatched[0];
 const existingSource=profile==='personal'&&firstUnmatched&&state.inventory?.some(item=>item.effects?.catalog_id===firstUnmatched[1].mod_id&&Number(item.level)===Number(firstUnmatched[1].mod_level)&&Number(item.stats?.original_observed_level??item.level)===Number(firstUnmatched[1].mod_level)&&item.stats?.observed_tooltip?.source_ref);
 const baseline=options.baseline_confirmed===true;
 const scenario=options.scenario_confirmed===true,tech=options.tech_confirmed===true;
 const checks=[
  {label:'Primary weapon',state:slots.primary?.catalog_id?'Selected in plan':'Not equipped in plan',kind:slots.primary?.catalog_id?'selected':'empty'},
  {label:'Armor',state:missingArmor.length?`${armor.length-missingArmor.length}/6 selected in plan; ${missingArmor.length} empty ${missingArmor.length===1?'slot':'slots'}`:'6/6 selected in plan',kind:missingArmor.length?'empty':'selected'},
  {label:'Selected mod levels',state:selectedMods.length?`${selectedMods.length-unmatched.length}/${selectedMods.length} exact level matches in ${profile==='new_player'?'New Player':'Personal'} profile${existingSource?'; existing screenshot available for review, not linked':''}`:'No mod equipped in plan; no mod tooltip is missing',kind:unmatched.length?'unknown':selectedMods.length?'selected':'empty'},
  {label:'Weapon baseline',state:baseline?'Unsaved pre-mod values entered for this preview':'Pre-mod damage, RPM, magazine and reload not entered for this plan',kind:baseline?'preview':'unknown'},
  {label:'Scenario and Tech',state:scenario&&tech?'Explicit unsaved what-if controls selected; activation is not game-verified':'No saved scenario or row-level Tech state; the controls below are unsaved what-ifs',kind:scenario&&tech?'preview':'capability_gap'},
  {label:'Deviation, food and other buffs',state:options.external_effect_entered?'Unsaved external-effect drafts are in Expert inputs; activation, duration and stacking still need review':'No structured buff or deviation is saved with this plan. Expert inputs allow up to three unsaved typed-effect what-ifs.',kind:'capability_gap'},
  {label:'Set and unique gear effects',state:'Gear can be selected, but set and unique effects need verified rules before entering damage totals',kind:'unmodeled'}
 ];
 if(!slots.primary?.catalog_id)return {next:'Choose a primary weapon for this saved plan.',action:{kind:'gear',slot:'primary'},checks};
 if(missingArmor.length)return {next:`Add ${missingArmor[0]} armor to this saved plan. Its slot is empty; this says nothing about what you own.`,action:{kind:'gear',slot:missingArmor[0]},checks};
 if(firstUnmatched)return {next:`Review ${guideModName(firstUnmatched[1].mod_id)} Lv ${firstUnmatched[1].mod_level??'?'} in the ${profile==='new_player'?'New Player':'Personal'} profile.${existingSource?' Its existing screenshot is available; no new recording is required.':''}`,action:{kind:'mod',slot:firstUnmatched[0],mod_id:firstUnmatched[1].mod_id},checks};
 if(!baseline)return {next:'Enter this weapon’s pre-mod baseline to see a supported partial calculation.',action:{kind:'baseline'},checks};
 if(!scenario||!tech)return {next:'Choose a scenario what-if below. Forge does not yet store verified Tech activation for each row, so the checkbox remains an assumption.',action:{kind:'scenario'},checks};
 return {next:'No saved setup gap remains in this preview. Record fight observations before interpreting a full DPS total.',action:null,checks};
}
function guideBuildChecklistHtml(build,profile,options={}){
 const plan=guideBuildChecklist(build,profile,options),action=plan.action;
 const click=action?.kind==='gear'?`guideOpenBuildEditor('${action.slot}','gear')`:action?.kind==='mod'?`guideOpenProfileMod('${esc(action.mod_id)}')`:action?.kind==='baseline'?"guideFocusChecklistInput('guideBuildHit')":action?.kind==='scenario'?"guideFocusChecklistInput('cf-Scenario')":null;
 const label=action?.kind==='gear'?'Open saved plan in editor':action?.kind==='mod'?'Review this profile’s mod':action?.kind==='baseline'?'Enter pre-mod values':action?.kind==='scenario'?'Check scenario and Tech':null;
 return `<div class="note guide-build-checklist"><b>Complete this build · next action</b><p>${esc(plan.next)}</p>${click?`<button class="secondary" type="button" onclick="${click}">${esc(label)} →</button>`:''}<details><summary>Other setup checks · ${plan.checks.length}</summary><ul>${plan.checks.map(row=>`<li><b>${esc(row.label)}:</b> ${esc(row.state)}</li>`).join('')}</ul><p class="small muted">Empty gear slots are not proof you lack the items. Entered values and assumptions remain unsaved until you explicitly save a build or profile. Known component subtotals can be useful while full DPS remains unresolved.</p></details></div>`;
}
function guideRenderBuildChecklist(){const target=$('#guideBuildChecklist');if(!target)return;const build=(state.planned_builds||[]).find(item=>item.id===val('guideBuildId'));target.innerHTML=guideBuildChecklistHtml(build,val('guideBuildProfile'),{baseline_confirmed:['guideBuildHit','guideBuildRpm','guideBuildMag','guideBuildReload'].every(id=>Number(val(id))>0),external_effect_entered:['cf-ExternalName','cf-ExternalName-1','cf-ExternalName-2'].some(id=>!!$('#'+id)?.value)})}
async function guideOpenBuildEditor(slot,mode){try{const id=val('guideBuildId');await ensureBuilder();document.body.classList.remove('mobile-nav-open');pushForgePage('builder');page='builder';comparison=null;if(id)openPlannedBuild(id);else render();if(slot)selectCharacterSlot(slot,mode);$('#view')?.focus();window.scrollTo(0,0)}catch(error){fail(error)}}
async function guideOpenProfileMod(id){startProfile=val('guideBuildProfile');await startOpenMods();if(id)await fieldGuideCardClick(id)}
function guideFocusChecklistInput(id){const details=$('#guideBaselineDetails');if(id==='guideBuildHit'&&details)details.open=true;const input=$('#'+id);input?.scrollIntoView?.({block:'nearest'});input?.focus?.()}
function guideBuildProfileChanged(){
 invalidateGuideBuildPreview();const select=$('#guideTopCandidate');if(select)select.innerHTML=guideTopOptions(val('guideBuildProfile'));
 const formula=$('#cf-Build'),newPlayer=val('guideBuildProfile')==='new_player';
 const evidence=$('#cf-ModEvidence');if(evidence&&newPlayer){evidence.value='owned_instances';evidence.disabled=true}else if(evidence)evidence.disabled=false;
 if(formula){formula.disabled=newPlayer;formula.value=newPlayer?'':val('guideBuildId');cfGuideUpdate()}
 const boundary=$('#cf-ProfileBoundary');if(boundary)boundary.textContent=newPlayer?'New Player is an empty collection preview. Saved-build formula selection is paused so Personal owned rolls cannot enter it.':'Choose exact owned instances or exact-level Personal Field Guide rows as the calculation source. Either path still requires Tech and formula evidence.';
 guideRenderBuildChecklist();
}
function guideRowKey(row){return [row.selected_slot||'',row.row_index,row.stat_type,row.raw_text].join('|')}
function guideRowsHtml(result,heading,activationAssumed=false){
 const rows=result.rows||[],modifiers=result.scenario?.modifiers||{};
 const used=new Set((modifiers.used_rows||[]).map(guideRowKey));
 const gated=new Set((modifiers.tech_gated_rows||[]).map(guideRowKey));
 const unmodeled=new Set((modifiers.unmodeled_rows||[]).map(guideRowKey));
 const messages=rows.map(row=>{
  const key=guideRowKey(row),amount=row.value==null?'amount or sign unknown':`${row.value}${row.unit==='percent'?'%':row.unit?' '+row.unit:''}`;
  const notes=[];
  if(gated.has(key))notes.push('Excluded: activation is unconfirmed for this scenario');
  if(unmodeled.has(key)||row.calculation_status==='unmodeled')notes.push('Effect not modeled by this formula');
  if(row.value==null)notes.push('No numeric contribution until this value is resolved');
  if(used.has(key))notes.push('Included only in the isolated model under the displayed assumptions');
  if(!notes.length)notes.push('No supported calculation for this row');
  const evidence=row.evidence||{};
  const sourceLink=evidence.source_frame?` · <a href="/${esc(evidence.source_frame)}" target="_blank" rel="noopener">Source frame</a>`:'';
  return `<li><b>${esc(row.selected_slot||'Top')} row ${esc((row.row_index??0)+1)}:</b> ${esc(row.raw_text||row.stat_type||'Source text unavailable')} <span class="small">(${esc(amount)})</span><br><span class="small muted">${esc(notes.join('; '))}. Activation: ${esc(row.tech_activation||'unknown')}; source: ${esc(row.confidence||'unverified')}${evidence.timestamp!=null?` · ${esc(evidence.timestamp)}s`:''}${sourceLink}.</span></li>`;
 });
 return `<div class="note"><b>${esc(heading)}</b><p class="small">Unconfirmed activation is ${activationAssumed?'treated as active only for this what-if':'excluded from the calculation'}. This includes unresolved Tech, gear-tier and other conditions.</p>${rows.length?`<ol>${messages.join('')}</ol>`:'<p>No exact selected Field Guide rows reach this preview.</p>'}</div>`;
}
const AAO_INTERACTION_SOURCES={
  savior:'https://www.oncehuman.game/news/update/20251029/40780_1267745.html',
  aao:'https://www.oncehumandb.com/mods/against-all-odds-battle',
  official:'https://www.oncehuman.game/news/devBlog/20250922/40781_1260687.html'
};
function interactionTimes(raw,duration,label){
  const values=String(raw||'').trim();if(!values)return [];
  return values.split(',').map(v=>{const t=Number(v.trim());if(!v.trim()||!Number.isFinite(t)||t<0||t>duration)throw Error(label+' times must be between 0 and the encounter end');return t}).sort((a,b)=>a-b);
}
function conditionalInteractionModel(input){
  const n=(key,min,max)=>{if(input[key]===null||input[key]===undefined||String(input[key]).trim()==='')throw Error(key+' is required');const v=Number(input[key]);if(!Number.isFinite(v)||v<min||v>max)throw Error(key+' must be between '+min+' and '+max);return v};
  const maxHp=n('max_hp',1,10000000),startHp=n('start_hp',0,maxHp),costFraction=n('cost_percent',0,100)/100;
  const base=n('base_percent',0,1000),perStack=n('per_stack_percent',0,1000),duration=n('duration_seconds',0,3600);
  const saviorDuration=input.savior_duration_seconds==null||String(input.savior_duration_seconds).trim()===''?null:n('savior_duration_seconds',0,3600);
  const costTimes=interactionTimes(input.cost_times,duration,'HP-cost'),refreshTimes=interactionTimes(input.refresh_times,duration,'Savior refresh');
  const threshold=.05*maxHp,stackCap=3,windowSeconds=5;
  let hp=startHp,residual=0,models={inclusive:0,strict:0,accumulator:0},expiry={inclusive:null,strict:null,accumulator:null};
  const timeline=[];const events=[...costTimes.map(time=>({time,type:'hp_cost'})),...refreshTimes.map(time=>({time,type:'savior_refresh'})),{time:duration,type:'end'}].sort((a,b)=>a.time-b.time||({hp_cost:0,savior_refresh:1,end:2}[a.type]-{hp_cost:0,savior_refresh:1,end:2}[b.type]));
  let lastSaviorRefresh=null;
  for(const event of events){
    for(const key of Object.keys(models))if(expiry[key]!=null&&event.time>=expiry[key]){models[key]=0;expiry[key]=null}
    let cost=0,added={inclusive:0,strict:0,accumulator:0};
    if(event.type==='hp_cost'){
      cost=hp*costFraction;hp-=cost;
      const ratio=cost/threshold;
      added.inclusive=Math.floor(ratio+1e-9);
      added.strict=Math.max(0,Math.ceil(ratio-1e-9)-1);
      residual+=cost;added.accumulator=Math.floor(residual/threshold+1e-9);residual-=added.accumulator*threshold;
      for(const key of Object.keys(models))if(added[key]>0){models[key]=Math.min(stackCap,models[key]+added[key]);expiry[key]=event.time+windowSeconds}
    }else if(event.type==='savior_refresh')lastSaviorRefresh=event.time;
    timeline.push({time:event.time,type:event.type,cost,remaining_hp:hp,added:{...added},stacks:{...models},aao_expires_at:{...expiry},savior_last_refresh:lastSaviorRefresh,savior_expires_at:lastSaviorRefresh!=null&&saviorDuration!=null?lastSaviorRefresh+saviorDuration:null,
      assumed_same_stat_bonus_percent:Object.fromEntries(Object.entries(models).map(([k,v])=>[k,base+v*perStack]))});
  }
  return {timeline,threshold_hp:threshold,remaining_hp:hp,base_percent:base,per_stack_percent:perStack,max_stacks:stackCap,aao_window_seconds:windowSeconds,
    assumptions:['Unsaved sensitivity: AAO Battle values are entered, not read from the selected player profile.','Inclusive, strict and cumulative threshold interpretations are alternatives, not verified game rules.','Only explicitly entered HP-cost times spend HP; Savior refresh hits never create an HP-cost event or refresh the AAO timer.','Each HP-cost event is modeled as a fraction of HP immediately before that event. No healing, other costs or shield depletion are inferred.','The cumulative carry alternative retains partial HP costs indefinitely until enough cost accumulates; its lifetime is not verified.','Base and stack bonuses are added only within the same named Weapon/Status stat for this illustration. Full damage bucket stacking and event uptime remain unresolved.'],sources:AAO_INTERACTION_SOURCES};
}
function invalidateInteractionPreview(){const node=$('#guideInteractionResult');if(node)node.innerHTML='<p class="small muted">Inputs changed. Preview again to update the timeline.</p>'}
function interactionExample(){
  const optional=$('#interactionSaviorDuration');if(optional)optional.value='';
  const fields={interactionMaxHp:'1000',interactionStartHp:'625',interactionCost:'8',interactionBase:'10',interactionPer:'5',interactionDuration:'6',interactionCosts:'0',interactionRefresh:'1,2,3,4,6'};
  for(const [id,value] of Object.entries(fields)){const node=$('#'+id);if(node)node.value=value}
  const node=$('#guideInteractionResult');if(node)node.innerHTML='<p class="note warn">Synthetic values loaded. They are not your saved gear or measured fight events. Run the preview to compare rule interpretations.</p>';
}
function previewConditionalInteraction(){try{
  const id=val('guideBuildId'),build=(state.planned_builds||[]).find(row=>row.id===id);
  if(!build)throw Error('Choose a saved planned build first');
  const model=conditionalInteractionModel({max_hp:val('interactionMaxHp'),start_hp:val('interactionStartHp'),cost_percent:val('interactionCost'),base_percent:val('interactionBase'),per_stack_percent:val('interactionPer'),duration_seconds:val('interactionDuration'),savior_duration_seconds:val('interactionSaviorDuration'),cost_times:val('interactionCosts'),refresh_times:val('interactionRefresh')});
  const boots=build.slots?.shoes?.mod_id||build.slots?.boots?.mod_id||null;
  const bootContext=boots?.includes('against-all-odds')?'The selected plan names Against All Odds for Shoes; its exact level effect is still not assumed here.':boots?'The selected plan has a different Shoes mod. Against All Odds is an unsaved hypothetical replacement, not an additional equipped mod.':'The selected plan has no Shoes mod recorded. Against All Odds is an unsaved hypothetical choice.';
  const saviorCount=Object.entries(build.slots||{}).filter(([slot,item])=>['helmet','top','bottoms','shoes','gloves','mask'].includes(slot)&&String(item?.catalog_id||'').includes('savior')).length;
  const row=x=>`<tr><td>${esc(x.time)}s</td><td>${x.type==='hp_cost'?'Entered HP cost':x.type==='savior_refresh'?'Savior-only refresh':'Encounter end'}</td><td>${x.type==='hp_cost'?esc(x.cost.toFixed(3))+' HP':'0 HP'}</td><td>${esc(x.remaining_hp.toFixed(3))}</td><td>${esc(x.stacks.inclusive)} / ${esc(x.stacks.strict)} / ${esc(x.stacks.accumulator)}</td><td>${x.aao_expires_at.inclusive==null?'—':esc(x.aao_expires_at.inclusive)+'s'} / Savior ${x.savior_expires_at==null?'unknown':esc(x.savior_expires_at)+'s'}</td></tr>`;
  $('#guideInteractionResult').innerHTML=`<div class="note"><b>${esc(build.name)} · unsaved conditional comparison</b><p>${esc(bootContext)} ${saviorCount} Savior armor piece(s) are recorded in this plan; an incomplete plan is not proof that the real character lacks the set.</p><p>AAO source lists a 5% of Max HP threshold, a 5-second stack window and up to 3 stacks for Battle. Entered base ${esc(model.base_percent)}% + ${esc(model.per_stack_percent)}% per stack is a hypothetical same-stat addition. A Savior-only refresh does not spend HP here. In the carry alternative, partial HP costs persist indefinitely until used; the game lifetime is unknown.</p><div class="interaction-scroll"><table class="interaction-table"><thead><tr><th>Time</th><th>Event</th><th>HP cost</th><th>HP left</th><th>AAO stacks: ≥ / &gt; / carry</th><th>AAO expiry / Savior expiry</th></tr></thead><tbody>${model.timeline.map(row).join('')}</tbody></table></div><p>At ${esc(model.timeline.at(-1).time)}s: AAO same-stat addition under ≥ / &gt; / carry alternatives: ${Object.values(model.timeline.at(-1).assumed_same_stat_bonus_percent).map(v=>esc(v.toFixed(2))+'%').join(' / ')}. This is not total DPS or a prediction of Savior shield duration.</p><details><summary>Rules, limits and sources</summary><ul>${model.assumptions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>${sourceReference(model.sources.savior,'Official Savior refresh change')} · ${sourceReference(model.sources.aao,'AAO Battle listing')} · ${sourceReference(model.sources.official,'Official AAO rework')}</details></div>`;
 }catch(error){fail(error)}
}
function conditionalInteractionPane(){return `<details class="card" style="margin-top:14px" oninput="invalidateInteractionPreview()" onchange="invalidateInteractionPreview()"><summary><b>HP-cost interaction · Savior + Against All Odds</b> · unsaved sensitivity</summary><p>Use the saved plan selected above. This preview changes no gear. Enter an HP-cost event only when HP was actually consumed; shield refresh shots go in the separate box.</p><p class="small">The selected plan may not include Against All Odds or three Savior pieces. Source-listed Battle magnitudes are not mapped to your owned level, so enter the magnitudes you want to test.</p><div class="formgrid"><label>Max HP<input id="interactionMaxHp" type="number" min="1" placeholder="enter"></label><label>HP before first cost<input id="interactionStartHp" type="number" min="0" placeholder="enter"></label><label>HP cost per event (% current HP)<input id="interactionCost" type="number" min="0" max="100" step="any" placeholder="enter"></label><label>Fight end (s)<input id="interactionDuration" type="number" min="0" step="any" placeholder="enter"></label><label>AAO base Weapon/Status (%)<input id="interactionBase" type="number" min="0" step="any" placeholder="enter"></label><label>AAO per stack (%)<input id="interactionPer" type="number" min="0" step="any" placeholder="enter"></label><label>HP-cost times (s)<input id="interactionCosts" placeholder="e.g. 0, 12"></label><label>Savior-only refresh times (s)<input id="interactionRefresh" placeholder="e.g. 1, 2, 3"></label><label>Savior buff duration (s, optional)<input id="interactionSaviorDuration" type="number" min="0" step="any" placeholder="unknown"></label></div><div class="actions"><button class="secondary" onclick="interactionExample()">Load synthetic example</button><button class="primary" onclick="previewConditionalInteraction()">Preview separate timers</button></div><div id="guideInteractionResult" aria-live="polite"></div></details>`}
function fieldGuideComparePane(){return `<details class="card field-guide-compare" style="margin-top:18px"><summary><b>Use saved gear (optional)</b> · profile and exact-roll coverage</summary><p>Choose a saved plan and a Field Guide profile. Exact variant and level matches can enter a partial calculation. A blank player never borrows Personal progress or legacy Backpack records.</p><div class="formgrid"><label>Collection profile<select id="guideBuildProfile" onchange="guideBuildProfileChanged()"><option value="personal">My existing profile</option><option value="new_player">New player · empty</option></select></label><label>Saved planned build<select id="guideBuildId" onchange="guideBuildChanged()"><option value="">Choose a plan</option>${(state.planned_builds||[]).map(b=>`<option value="${esc(b.id)}">${esc(b.name)} · ${esc(b.id.slice(0,8))}</option>`).join('')}</select></label></div><div id="guideBuildChecklist">${guideBuildChecklistHtml(null,'personal')}</div><label>Top mod to test without saving<select id="guideTopCandidate" onchange="invalidateGuideBuildPreview()">${guideTopOptions('personal')}</select></label><p class="small" id="guideTopContext">${esc(guideTopContext(null))}</p><details id="guideBaselineDetails" oninput="guideRenderBuildChecklist()" onchange="guideRenderBuildChecklist()"><summary>Optional pre-mod what-if baseline</summary><div class="formgrid"><label>Direct hit<input id="guideBuildHit" oninput="invalidateGuideBuildPreview()" type="number" min="0" step="any" placeholder="unknown"></label><label>RPM<input id="guideBuildRpm" oninput="invalidateGuideBuildPreview()" type="number" min="0" step="any" placeholder="unknown"></label><label>Magazine<input id="guideBuildMag" oninput="invalidateGuideBuildPreview()" type="number" min="0" step="any" placeholder="unknown"></label><label>Reload seconds<input id="guideBuildReload" oninput="invalidateGuideBuildPreview()" type="number" min="0" step="any" placeholder="unknown"></label></div><label><input id="guideBuildTech" onchange="invalidateGuideBuildPreview()" type="checkbox"> Hypothetical: treat unconfirmed activation as active</label><p class="small">Use only a baseline before these mod effects; already modified hits would double count them. Activation can depend on Tech, gear tier or other conditions that are not yet confirmed.</p></details><button class="secondary" onclick="previewSelectedProfileBuild()">Explain selected profile rows</button><div id="guideBuildResult" aria-live="polite"></div>${conditionalInteractionPane()}</details>`}
function guideModName(id){const entry=catalogEntry(id);return entry?`${entry.name}${entry.variant?` <${entry.variant}>`:''}`:String(id||'Unidentified mod').replace(/^mod:[^:]+:/,'').replaceAll('-', ' ')}
function guideIssueText(issue){const reason=issue.reason||'';if(reason.includes('no unlocked level'))return 'No level is recorded in this profile';if(reason.includes('level differs'))return `Saved Lv ${issue.selected_level??'?'} differs from profile Lv ${issue.profile_level??'?'}`;if(reason.includes('physical inventory'))return 'Linked to an existing inventory record; profile replacement is not automatic';if(reason.includes('multiple active slots'))return 'The same variant appears in multiple active slots';return reason||'Evidence needs review'}
function guideBuildNextAction(result,top,profile){
 const selected=result.selected||[],issues=result.issues||[],label=profile==='new_player'?'New player':'Personal';
 if(!selected.length&&!issues.length)return `<div class="note"><b>Next step: choose a mod for this plan.</b><p>No mod is selected in the saved plan, so there are no saved mod rolls to calculate. ${top?'The Top choice below is an unsaved candidate only.':''}</p><button class="secondary" onclick="go('builder')">Open build editor →</button></div>`;
 if(issues.length){const issue=issues[0],missing=String(issue.reason||'').includes('no unlocked level');return `<div class="note"><b>Next step: ${missing?'record this mod’s level':'review this saved mod selection'}.</b><p>${esc(guideModName(issue.catalog_id))} · ${esc(guideIssueText(issue))}. ${label} progress is used only for an exact variant and level match.</p><button class="secondary" onclick="${missing?`startProfile='${profile}';startOpenMods()`:`go('builder')`}">${missing?'Open this profile’s Mods':'Open build editor'} →</button></div>`}
 return `<div class="note"><b>Next step: check activation and a pre-mod baseline.</b><p>${selected.length} saved mod selection${selected.length===1?' has':'s have'} source rows. Their effect is not assumed active, and a modeled direct hit still needs the pre-mod inputs. ${top?'The Top candidate below remains unsaved.':''}</p></div>`;
}
function guideSavedSummary(result){const selected=result.selected||[],issues=result.issues||[];return `<details><summary>Saved mod details · ${selected.length} matched, ${issues.length} needing review</summary><ul>${selected.map(x=>`<li>${esc(x.slot)} · ${esc(guideModName(x.catalog_id))} · ${x.status==='inactive_weapon'?'Inactive weapon; excluded':`Lv ${esc(x.level??'?')} · source rows available; activation not confirmed`}</li>`).join('')}${issues.map(x=>`<li>${esc(x.slot)} · ${esc(guideModName(x.catalog_id))}: ${esc(guideIssueText(x))}</li>`).join('')}</ul></details>`}
async function previewSelectedProfileBuild(){let request,profile,build,top;try{
 const target=$('#guideBuildResult'),profile=val('guideBuildProfile'),build=val('guideBuildId'),top=val('guideTopCandidate');request=++guideBuildRequest;
 if(!build)throw Error('Choose a saved planned build');
 const hit=val('guideBuildHit'),rpm=val('guideBuildRpm'),mag=val('guideBuildMag'),reload=val('guideBuildReload');
 if(hit&&(!rpm||!mag||reload===''))throw Error('Enter all four pre-mod baseline values together');
 const baseline=hit?{base_origin:'pre_mod_unbuffed',base_direct_hit:Number(hit),rpm:Number(rpm),magazine:Number(mag),reload_seconds:Number(reload),tech_policy:$('#guideBuildTech').checked?'assume_active':'exclude_unknown'}:{base_origin:'unknown',tech_policy:$('#guideBuildTech').checked?'assume_active':'exclude_unknown'};
 const [result,topResult]=await Promise.all([
  api('field-guide/build-preview',{profile_id:profile,build_id:build,baseline}),
  top?api('field-guide/calculation-preview',{profile_id:profile,catalog_id:top,baseline}):Promise.resolve(null)
 ]);
 if(request!==guideBuildRequest||!$('#guideBuildResult')||val('guideBuildProfile')!==profile||val('guideBuildId')!==build||val('guideTopCandidate')!==top)return;
 const topHtml=topResult?`<p class="note warn"><b>Unsaved Top candidate:</b> ${esc(guideModName(top))} · recorded Lv ${esc(topResult.level??'?')}. This separate preview does not equip it or establish full build DPS.</p>${guideRowsHtml(topResult,'Candidate rows and calculation status',baseline.tech_policy==='assume_active')}${topResult.scenario?.component_results?`<p>With only this candidate and the entered pre-mod baseline, isolated direct hit: ${esc(guideNumber(topResult.scenario.component_results.direct_hit))}. This is not a saved-build total.</p>`:''}`:'<p class="small">No unsaved Top candidate is being tested. Choose one above only if you want a separate preview.</p>';
 target.innerHTML=`<details><summary>More evidence guidance</summary>${guideBuildNextAction(result,top,profile)}</details><div class="note"><b>${esc(result.build_name)} · ${profile==='new_player'?'New player':'Personal'} profile</b><p>${result.rows.length} rows from matching saved mods. Full build damage is unresolved; excluded effects are not zero damage.</p>${result.scenario.component_results?`<p>Modeled direct hit: ${esc(guideNumber(result.scenario.component_results.direct_hit))} under entered assumptions. This is a partial calculation, not measured damage or total DPS.</p>`:''}${guideSavedSummary(result)}</div>${guideRowsHtml(result,'Rows from the saved plan',baseline.tech_policy==='assume_active')}${topHtml}`;
}catch(e){if(request!==guideBuildRequest||!$('#guideBuildResult')||val('guideBuildProfile')!==profile||val('guideBuildId')!==build||val('guideTopCandidate')!==top)return;fail(e)}}
function toggleChoice(id,on){chosen=on?[...new Set([...chosen,id])]:chosen.filter(x=>x!==id)}
let editBuildId=null;
function loadBuild(id){let b=state.loadouts.find(x=>x.id===id);chosen=[...b.item_ids];editBuildId=id;render();$('#buildName').value=b.name;$('#buildNotes').value=b.notes||''}
async function saveBuild(){try{let ids=[...chosen];await api('loadout',{id:editBuildId||undefined,name:val('buildName'),notes:val('buildNotes'),item_ids:ids});editBuildId=null;chosen=[];await refresh();notice('Build saved')}catch(e){fail(e)}}
function comparePage(){return `${structuredComponentCard()}${plannedComparisonCard()}${componentCompareCard()}${fieldGuideComparePane()}${combatFormulaCard()}<div class="card" style="margin-top:18px"><div class="kicker">OPTIONAL TEST · NO SAVE</div><h2>Prepare a calibration test</h2><p>Use a plain-language worksheet to record exact gear, Tech state, pre-effect reload and separate bullet, Power Surge and AUG orb observations. Download a blank or filled JSON record; no inventory or build changes.</p><a href="/calibration-worksheet">Open calibration test worksheet</a></div><details class="cf-other-comparisons"><summary>Other expert comparisons</summary>${augCalibrationCard()}<div class="card planned-jump"><div class="kicker">CATALOG PLANS</div><h2>Compare saved planned builds</h2><p>Duplicate a planned build, change a piece, save the copy, and compare both versions with catalog-backed effects and known attributes. Confirmed inventory is not required.</p><button class="primary" onclick="go('builder')">Open Build editor</button></div><div class="grid two"><div class="card"><div class="kicker">COMPARISON SETUP</div><h2>Choose evidence mode</h2><div class="field"><label>Comparison basis</label><select id="comparisonMode" onchange="comparisonModeChanged()"><option value="predicted_equipment">Predicted equipment proxy · sourced isolated rules</option><option value="measured_baseline">Measured baseline · exact loadout and context</option></select></div><div class="formgrid"><div class="field"><label>Fight duration (s)</label><input id="duration" type="number" value="45"></div><div class="field"><label>Hit accuracy (0–1)</label><input id="hitRate" type="number" min="0" max="1" step=".05" value="0.8"></div><div class="field"><label>Weak-spot share (0–1)</label><input id="weakRate" disabled type="number" min="0" max="1" step=".05" value="0"></div><div class="field"><label>Crit share (0–1)</label><input id="critRate" disabled type="number" min="0" max="1" step=".05" value="0"></div><div class="field"><label>Scenario</label><select id="scenario"><option>PvE</option><option>PvP</option><option>RaidZone</option></select></div><div class="field"><label>Goal</label><select id="goal"><option>Sustained baseline</option><option>Burst baseline</option><option disabled>Boss damage</option><option disabled>Group clearing</option><option disabled>Ease of use</option></select></div><div class="field"><label>HP fraction for set rule</label><input id="hpFraction" type="number" min="0" max="1" step=".05" placeholder="required for Tides"></div></div><div id="measurementContext" hidden><div class="field"><label>Use saved measurement context</label><select id="contextPreset" onchange="useMeasurementContext()"><option value="">Choose a saved context or enter one below</option>${(state.measurements||[]).map(m=>`<option value="${m.id}">${esc(m.target)} · ${esc(m.scenario)} · ${esc(m.buffs||'no buffs')} · ${esc(m.conditions||'no conditions')}</option>`).join('')}</select></div><div class="formgrid"><div class="field"><label>Target identity</label><input id="target" placeholder="same enemy / dummy"></div><div class="field"><label>Buffs</label><input id="buffs" placeholder="exact active buffs"></div><div class="field"><label>Conditions</label><input id="conditions" placeholder="range, stance, difficulty"></div></div></div><p class="tagline">Predicted mode treats tooltip Damage as a relative proxy and uses only isolated sourced rules. Measured mode requires a saved hit and firing cycle for each exact loadout under the same target, buffs and conditions. Combat hits never transfer between gear combinations.</p><details><summary>Lock or exclude owned items</summary><div class="list" style="margin-top:12px">${state.inventory.map(i=>`<div class="row"><span>${esc(i.name)} · ${esc(i.slot||'unknown')}</span><label>Lock <input type="checkbox" class="lockItem" value="${i.id}"></label><label>Exclude <input type="checkbox" class="excludeItem" value="${i.id}"></label></div>`).join('')}</div></details><div class="actions" style="margin-top:16px"><button class="primary" onclick="runCompare()">Compare saved builds</button><button class="secondary" id="searchButton" onclick="runSearch()">Search legal owned combinations</button><button class="secondary" onclick="showCatalog()">Ideal paths / missing pieces</button></div></div><div class="card"><h2>Record a combat measurement</h2><p class="tagline">Attach a normal hit and firing cycle to the exact saved loadout. Optionally add measured crit and weak-spot hits. Record the target and conditions so comparisons use like-for-like evidence.</p><div class="formgrid"><div class="field"><label>Build</label><select id="mBuild"><option value="">Select build</option>${state.loadouts.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label>Target</label><input id="mTarget" placeholder="enemy/dummy ID"></div><div class="field"><label>Scenario</label><select id="mScenario"><option>PvE</option><option>PvP</option><option>RaidZone</option></select></div><div class="field"><label>Normal hit</label><input id="mNormal" type="number" min="1"></div><div class="field"><label>Crit hit</label><input id="mCrit" type="number" min="1" placeholder="optional"></div><div class="field"><label>Weak-spot hit</label><input id="mWeak" type="number" min="1" placeholder="optional"></div><div class="field"><label>Crit weak-spot hit</label><input id="mCritWeak" type="number" min="1" placeholder="optional"></div><div class="field"><label>RPM with this loadout</label><input id="mRpm" type="number" min="1"></div><div class="field"><label>Magazine with this loadout</label><input id="mMag" type="number" min="1"></div><div class="field"><label>Reload seconds with this loadout</label><input id="mReload" type="number" min="0" step=".1"></div><div class="field"><label>Buffs</label><input id="mBuffs" placeholder="exact active buffs"></div><div class="field"><label>Conditions</label><input id="mConditions" placeholder="range, stance, difficulty"></div></div><div class="field" style="margin-top:10px"><label>Source frame (optional)</label><select id="mSource"><option value="">Manually observed, no imported frame</option>${state.observations.map(o=>`<option value="${o.id}">${esc(o.fields?.name?.value||'Frame')} · ${o.timestamp||0}s</option>`).join('')}</select></div><button class="secondary" onclick="saveMeasurement()">Save contextual measurement</button><p class="footertext">${state.measurements?.length||0} contextual measurements saved.</p></div></div><div class="card" style="margin-top:18px"><div class="kicker">CONFIRMED INVENTORY · SAME SLOT</div><h2>Compare two owned selections</h2><p class="tagline">Inspect catalog resolved attributes and activation before recording a weapon. This comparison can explain component changes even when total damage is unresolved.</p><div class="formgrid"><div class="field"><label>Current selection</label><select id="selectionLeft" onchange="selectionSlotChanged()"><option value="">Select confirmed gear</option>${state.inventory.filter(i=>['instance','mod_unlock'].includes(i.kind)&&i.slot).map(i=>`<option value="${esc(i.id)}">${esc(i.name)} · ${esc(i.variant||'')} · Lv ${esc(i.level??'?')} · ${esc(i.slot)}</option>`).join('')}</select></div><div class="field"><label>Alternative in same slot</label><select id="selectionRight"><option value="">Select current first</option></select></div><div class="field"><label>Selected weapon family / effect</label><input id="selectionFamily" placeholder="e.g. Power Surge, Burn, direct hit"></div><div class="field"><label>Encounter conditions</label><input id="selectionConditions" placeholder="e.g. grounded, no incoming hits"></div><div class="field"><label>Weapon base trigger chance (0–1, optional)</label><input id="selectionBaseChance" type="number" min="0" max="1" step=".01" placeholder="e.g. 0.30"></div><div class="field"><label>Critical-hit share (0–1, optional)</label><input id="selectionCritRate" type="number" min="0" max="1" step=".01" placeholder="unknown until entered"></div><div class="field"><label>Weak-spot share (0–1, optional)</label><input id="selectionWeakRate" type="number" min="0" max="1" step=".01" placeholder="unknown until entered"></div><div class="field"><label>Isolated first monster hit (optional)</label><input id="selectionIncomingHit" type="number" min="0" step="1" placeholder="e.g. 100 before this mod"></div></div><button class="primary" onclick="runSelectionCompare()">Explain this swap</button><button class="secondary" onclick="runCatalogExample()">Try sourced Lv. 10 → 11 example (unowned)</button><div id="selectionResults" style="margin-top:16px"></div></div><div class="card" style="margin-top:18px"><div class="kicker">OUTGOING DAMAGE · CATALOG EXAMPLE</div><h2>Against All Odds vs Power of Striving</h2><p class="tagline">Two real boot mods on one illustrative direct-only primary and stationary PvE target. No example gear is added to owned inventory. Source-linked effects, explicit encounter inputs, three stacking sensitivities, and both magazine-rounding bounds appear in the result.</p><div class="formgrid"><div class="field"><label>Critical-hit share (0–1)</label><input id="outCrit" type="number" min="0" max="1" step=".05" value="0.2"></div><div class="field"><label>Weak-spot share (0–1)</label><input id="outWeak" type="number" min="0" max="1" step=".05" value="0.2"></div><div class="field"><label>Fight duration (s)</label><input id="outDuration" type="number" min="1" value="40"></div><div class="field"><label>Relative elevation</label><select id="outElevation"><option value="same">Same elevation</option><option value="different">Different elevation · suffix unresolved</option></select></div><label>Stamina spent <input id="outStamina" type="checkbox"></label><label>HP lost <input id="outHpLost" type="checkbox"></label><label>Weapon has proc/status output <input id="outProc" type="checkbox"></label></div><button class="primary" onclick="runOutgoingExample()">Calculate outgoing comparison</button><div id="outgoingResults" style="margin-top:16px"></div></div><div id="compareResults" style="margin-top:18px">${comparison?resultsHtml(comparison):''}</div></details>`}
function useMeasurementContext(){let m=(state.measurements||[]).find(x=>x.id===val('contextPreset'));if(!m)return;$('#target').value=m.target;$('#buffs').value=m.buffs;$('#conditions').value=m.conditions;$('#scenario').value=m.scenario}
function comparisonModeChanged(){let measured=val('comparisonMode')==='measured_baseline';$('#measurementContext').hidden=!measured;$('#weakRate').disabled=!measured;$('#critRate').disabled=!measured;$('#searchButton').disabled=measured;if(!measured){$('#weakRate').value=0;$('#critRate').value=0}}
async function saveMeasurement(){try{let d={build_id:val('mBuild'),target:val('mTarget'),scenario:val('mScenario'),normal_hit:num('mNormal'),crit_hit_damage:num('mCrit'),weakspot_hit_damage:num('mWeak'),crit_weakspot_hit_damage:num('mCritWeak'),rpm:num('mRpm'),magazine:num('mMag'),reload_seconds:num('mReload'),buffs:val('mBuffs'),conditions:val('mConditions'),source_observation:val('mSource')||null};await api('measurement',d);await refresh();notice('Measurement bound to this loadout and context')}catch(e){fail(e)}}
function assumptions(){return {duration:Number(val('duration')),hit_rate:Number(val('hitRate')),weakspot_rate:Number(val('weakRate')),crit_rate:Number(val('critRate')),hp_fraction:val('hpFraction')===''?null:Number(val('hpFraction')),scenario:val('scenario'),goal:val('goal'),comparison_mode:val('comparisonMode'),target:val('target'),buffs:val('buffs'),conditions:val('conditions')}}
function selectedIds(cls){return [...document.querySelectorAll('.'+cls+':checked')].map(x=>x.value)}
async function runSearch(){try{let d=await api('search',{assumptions:assumptions(),locked:selectedIds('lockItem'),excluded:selectedIds('excludeItem')});$('#compareResults').innerHTML=searchHtml(d)}catch(e){fail(e)}}
function searchHtml(d){return `<div class="sectionhead"><h2>Predicted equipment search</h2><span class="muted small">${d.searched} / ${d.space} searched</span></div><p class="note warn">${esc(d.reason||d.method)}. ${d.unsupported||0} combinations unresolved. ${d.winner_established?'All candidates were modeled and the leader is distinct.':'No overall equipment winner is established.'}</p><div class="grid two" style="margin-top:16px">${d.results?.length?d.results.slice(0,8).map((r,i)=>`<div class="card"><h3>${i+1}. ${esc(r.items.find(x=>x.slot==='primary')?.name||'Build')}</h3><p class="small muted">${r.items.map(x=>esc(x.name)).join(' · ')}</p><div class="metric">${r.score}</div><p class="small muted">${esc(r.metric.score_kind)} · factor ${r.metric.factor??1}</p>${r.metric.trace?.map(t=>`<p class="small">${esc(t.reason)} ${sourceReference(t.source,'source')}</p>`).join('')}</div>`).join(''):empty('No calculable combinations',d.reason||'Review tooltip origin and effect coverage. Unresolved gear cannot be ranked.')}</div>`}
function sourceUrl(id){if(!id)return '#';if(String(id).startsWith('data/media/'))return '/'+id;return state.knowledge.sources.find(s=>s.id===id)?.url||(/^(https?:)?\/\//.test(String(id))?id:'#')}
function sourceReference(id,label='Source'){
  const url=sourceUrl(id),name=state.knowledge.sources.find(s=>s.id===id)?.title||label;
  if(/^\/(?!\/)/.test(url)||/^https:\/\/(?:www\.)?oncehuman\.game\//.test(url))
    return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
  const host=/^https?:\/\/([^/]+)/.exec(url)?.[1]?.replace(/^www\./,'')||'unavailable';
  return `<span class="small muted">${esc(name)} · ${esc(host)} (third-party evidence; no external link)</span>`;
}
function selectionSlotChanged(){let current=state.inventory.find(i=>i.id===val('selectionLeft'));let options=state.inventory.filter(i=>i.id!==current?.id&&i.slot===current?.slot&&['instance','mod_unlock'].includes(i.kind));$('#selectionRight').innerHTML='<option value="">Select alternative</option>'+options.map(i=>`<option value="${esc(i.id)}">${esc(i.name)} · ${esc(i.variant||'')} · Lv ${esc(i.level??'?')}</option>`).join('')}
